select user,sys_context('USERENV','SERVICE_NAME') SERVICE_NAME from dual;
select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_STOCK_HU_PLACEMENT_CORE','RRL_HU_CLAIM_IDENTITY_GUARD','RRL_STOCK_CASE_RETURN_CMD') order by OBJECT_NAME,OBJECT_TYPE;
select NAME,TYPE,LINE,TEXT from USER_ERRORS where NAME in('RRL_STOCK_HU_PLACEMENT_CORE','RRL_HU_CLAIM_IDENTITY_GUARD','RRL_STOCK_CASE_RETURN_CMD') order by NAME,TYPE,LINE;
